-- Learning sources per skill: up to 3 links for each skill_name in onet_role_skills, tagged with the kind of
-- source that suits the skill. Source of the links: web search on 2026-10-22; each URL was requested once
-- and dead links (404/410) were dropped. Sites that block scripts (HTTP 403, a few timeouts) were kept but
-- could not be checked automatically.
--
-- source_type, chosen per skill from what the skill is (every source of a skill has the same type):
--   project     = hands-on build: programming languages, frameworks, databases, DevOps and data tools
--   certificate = a credential or formal course: vendor software with an official exam (AWS, Salesforce, SAP,
--                 Oracle, Microsoft Office, Azure...), regulated or professional knowledge areas
--   video       = lecture or tutorial video: academic subjects (physics, biology...), design and office apps,
--                 browsers, collaboration tools
--   activity    = practice exercises: soft skills (listening, negotiation, time management, ...)
--
-- skill_name matches onet_role_skills.skill_name. It is not a foreign key: skill_id is not unique per name
-- (tech:c covers both C and C++, and Mathematics appears under two ids).
-- Gaps (skills with no row, and skills with fewer than 3 sources) are listed at the end of this file.

create table public.skill_sources (
    source_id   bigint generated always as identity primary key,
    skill_name  text not null,
    source_type text not null check (source_type in ('project', 'certificate', 'activity', 'video')),
    rank        smallint not null check (rank between 1 and 3),   -- 1 = first pick for the skill
    title       text not null,
    url         text not null check (url ~ '^https?://\S+$'),
    unique (skill_name, url)
);

create index skill_sources_skill_idx on public.skill_sources (skill_name, rank);

-- Public read-only for the anon key, like the other reference tables. Only the service role writes.
alter table public.skill_sources enable row level security;
create policy "public read" on public.skill_sources for select to anon, authenticated using (true);


